# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.52.4/ankra-cli-darwin-arm64"
      sha256 "de98528d5c6cb2aae6e739e34581fedf5ffe765b581b57c056d7b07731f36065"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.52.4/ankra-cli-darwin-amd64"
      sha256 "09ee02f4c945520d73e84ce46e8150b6d74be74b9bddbf2b8ca3268f862a3985"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.52.4/ankra-cli-linux-arm64"
      sha256 "a79b1e63cf96f1d7b9619609ef22c45a8b4f865ad0ff83462d644e72f41701d6"
    end
    on_intel do
